import {BRANDS,BRAND_IDS,CHANNELS,PROFILES,OBJECTIVES,SCENARIOS} from './data.js';
import {defaults,sanitizeState,project,redistribute,finite,applyObjective,comparisonState} from './model.js';

const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(value,digits=0)=>new Intl.NumberFormat('es-CO',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(value);
const compact=value=>value>=1e6?`${number(value/1e6,2)} M`:value>=1e3?`${number(value/1e3,1)} mil`:number(value);
const money=value=>`$${number(value)}`;
const shortMoney=value=>value>=1e6?`$${number(value/1e6,value%1e6?1:0)} M`:money(value);
const pct=(value,digits=1)=>`${number(value,digits)}%`;
const cleanText=value=>value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const paths={
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M15 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 chart:'M4 3v17h17 M8 14l4-5 4 3 5-7',
 sliders:'M4 4v6m0 4v6 M12 4v10m0 4v2 M20 4v2m0 4v10 M1 10h6 M9 14h6 M17 6h6',
 target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l8-8 M16 4h4v4',
 globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18 M12 3c-5 5-5 13 0 18',
 download:'M12 3v12 M8 11l4 4 4-4 M4 16v5h16v-5',
 chevron:'m9 5 7 7-7 7',
 menu:'M4 6h16 M4 12h16 M4 18h16',
 info:'M12 16v-4 M12 8h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 click:'m5 3 14 9-7 1-3 7z M14 15l4 5',
 window:'M3 4h18v16H3z M3 9h18 M6 6.5h.01 M9 6.5h.01 M7 13h6 M7 16h10',
 spark:'m12 2 2.5 6.5L21 11l-6.5 2.5L12 20l-2.5-6.5L3 11l6.5-2.5z M20 2v4 M18 4h4',
 heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',
 activity:'M2 12h5l3-8 4 16 3-8h5',
 sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',
 search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0 M15 15l6 6',
 palette:'M12 3a9 9 0 1 0 0 18c2 0 3-2 1-3-1-1 0-3 2-3h3c5 0 3-12-6-12 M7 10h.01 M9 6h.01 M15 6h.01 M18 10h.01',
 clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 bag:'M5 7h14l2 14H3z M8 8V6a4 4 0 0 1 8 0v2',
 save:'M5 3h12l4 4v14H3V3z M7 3v6h10V3 M7 21v-7h10v7',
 reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',
 print:'M7 8V3h10v5 M7 17H3V8h18v9h-4 M7 14h10v7H7z M17 11h.01',
 check:'m5 12 4 4L19 6',
 layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',
 shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6'
};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const NAV=[['summary','Resumen','grid'],['audiences','Audiencias','users'],['media','Medios','layers'],['sim','Simulador','sliders']];
const KEY='jgb-audience-lab-v1';
let storageOK=true,state;
try{state=sanitizeState(JSON.parse(localStorage.getItem(KEY)))}catch{state=defaults();storageOK=false}
let brand='all',view='summary',query='',stage='all',curveMetric='reach',toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true}catch{storageOK=false;return false}}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3500)}
function route(){const parts=location.hash.slice(1).split('/');const old=brand;if(parts.length===1&&NAV.some(n=>n[0]===parts[0])){brand='all';view=parts[0]}else{brand=BRANDS[parts[0]]?parts[0]:'all';view=NAV.some(n=>n[0]===parts[1])?parts[1]:'summary'}if(old!==brand){query='';stage='all'}render();window.scrollTo({top:0,behavior:'instant'});}
function go(nextView,nextBrand=brand){const hash=`#${nextBrand}/${nextView}`;if(location.hash===hash){render();window.scrollTo({top:0,behavior:'instant'})}else location.hash=hash}
function brandStyle(id){return `--brand-color:${BRANDS[id].color};--brand-soft:${BRANDS[id].soft}`}
function countProfiles(){return PROFILES.filter(p=>brand==='all'||p.brand===brand)}
function header(title,description,kicker='AUDIENCE INTELLIGENCE'){return `<div class="page-heading"><div><span class="eyebrow">${kicker} / ${esc(BRANDS[brand].name)}</span><h1>${title}</h1><p>${description}</p></div><span class="heading-status">${icon('globe')}Colombia · Adultos 18+</span></div>`}
function shell(){const B=BRANDS[brand];document.body.dataset.brand=brand;document.documentElement.style.setProperty('--accent',B.color);document.documentElement.style.setProperty('--soft',B.soft);document.title=`${NAV.find(n=>n[0]===view)[1]} · ${B.name} | JGB Audience Lab`;
$('#sidebar').innerHTML=`<a class="wordmark" href="#all/summary" aria-label="JGB Audience Lab, vista general"><span class="jgb">JGB</span><span><strong>Audience Lab</strong><small>CONEXIONES QUE IMPORTAN</small></span></a><a class="overview-link ${brand==='all'?'selected':''}" href="#all/${view}">${icon('grid')}Vista general</a>${brand==='all'?`<nav class="side-subnav" aria-label="Secciones del portafolio">${NAV.map(([v,n])=>`<a href="#all/${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${n}</a>`).join('')}</nav>`:''}<div class="side-label">EXPLORA LAS MARCAS</div>${BRAND_IDS.map(id=>`<div class="brand-side ${brand===id?'selected':''}"><a class="brand-trigger" href="#${id}/${view}" ${brand===id?'aria-current="true"':''}><span class="brand-thumb ${id}"><img src="${BRANDS[id].image}" alt=""></span><span><b>${BRANDS[id].name}</b><small>${id==='tarrito'?'Nutrición y bienestar':id==='pads'?'Rutina facial':'Cuidado de la piel'}</small></span>${icon('chevron')}</a>${brand===id?`<nav class="side-subnav" aria-label="Secciones de ${BRANDS[id].name}">${NAV.map(([v,n])=>`<a href="#${id}/${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${n}</a>`).join('')}</nav>`:''}</div>`).join('')}<div class="side-bottom"><div class="planning-card">${icon('spark')}<strong>De la intuición a la proyección.</strong><p>Explora cuánto puede lograr tu próximo plan de medios.</p><button data-go="sim">Crear un escenario</button></div><div class="side-signature"><b>CO</b><span>Planeación Colombia<small>3 marcas · un solo lugar</small></span></div></div>`;
$('#topbar').innerHTML=`<button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menú de marcas" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="top-title">${icon('layers')}<span>JGB <small>/ ${esc(B.name)}</small></span></div><nav class="top-nav" aria-label="Navegación principal">${NAV.map(([v,n,i])=>`<a href="#${brand}/${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${n}</a>`).join('')}</nav><div class="top-actions"><span class="country"><i class="flag"></i>Colombia</span><button class="export-btn" data-action="export" aria-label="Exportar ${view==='audiences'?'audiencias':'plan'} CSV">${icon('download')}<span>Exportar</span></button></div>`;
$('#scrim').hidden=true;$('#sidebar').classList.remove('open');syncNavigation();}
function syncNavigation(){const mobile=window.matchMedia('(max-width:800px)').matches;$('#sidebar').inert=mobile&&!$('#sidebar').classList.contains('open');}
function render(){shell();const result=project(state,brand);$('#main').innerHTML=view==='summary'?summary(result):view==='audiences'?audiences():view==='media'?media(result):simulator(result);}
function kpis(r){return `<div class="kpi-grid"><article class="kpi"><div class="kpi-top"><span class="kpi-title">Alcance estimado</span><span class="kpi-icon">${icon('users')}</span></div><strong>${compact(r.reach)}</strong><small><b>${pct(r.coverage)}</b> de ${compact(r.universe)} de base</small></article><article class="kpi"><div class="kpi-top"><span class="kpi-title">Impresiones</span><span class="kpi-icon">${icon('target')}</span></div><strong>${compact(r.impressions)}</strong><small>Frecuencia media: <b>${number(r.frequency,2)}×</b></small></article><article class="kpi"><div class="kpi-top"><span class="kpi-title">Clics de enlace</span><span class="kpi-icon">${icon('click')}</span></div><strong>${compact(r.clicks)}</strong><small>CTR: <b>${pct(r.ctr,2)}</b> de impresiones</small></article><article class="kpi"><div class="kpi-top"><span class="kpi-title">Sesiones estimadas</span><span class="kpi-icon">${icon('window')}</span></div><strong>${compact(r.sessions)}</strong><small><b>${pct(r.arrival)}</b> de clics llegan a sesión</small></article></div>`}
function art(){return `<div class="hero-art ${brand==='all'?'':'single'}" aria-hidden="true"><div class="orbital"></div><span class="star">✧</span><span class="star second">✦</span><div class="product-stage"></div>${(brand==='all'?BRAND_IDS:[brand]).map(id=>`<img class="pack ${id}" src="${BRANDS[id].image}" alt="" fetchpriority="high">`).join('')}<span class="float-tag">${brand==='all'?'Un portafolio. Infinitas conexiones.':BRANDS[brand].category}</span></div>`}
function summary(r){const B=BRANDS[brand];return `${header(brand==='all'?'Tu próximo gran plan empieza aquí.':`El potencial de ${B.name}.`,brand==='all'?'Una mirada a tus marcas, sus audiencias y las posibilidades de tu inversión.':'Una estrategia propia, conectada con la vida cotidiana de las personas.','ESTRATEGIA / PLANEACIÓN')}<div class="hero-grid"><section class="hero" data-hero="${brand}"><div class="hero-copy"><span class="eyebrow">${B.tag}</span><h2>${B.title}</h2><p>${B.description}</p><button class="btn" data-go="audiences">${icon('users')}Explorar audiencias</button></div>${art()}</section><aside class="quick-card"><span class="eyebrow">TU ESCENARIO ACTUAL</span><h2>¿Hasta dónde<br>puedes llegar?</h2><div class="quick-budget">${shortMoney(r.spend)} <small>COP</small></div><p>${number(r.config.days)} días · Escenario ${SCENARIOS[r.config.scenario].name.toLowerCase()}</p><div class="quick-stats"><div><strong>${pct(r.coverage)}</strong><small>de cobertura</small></div><div><strong>${compact(r.sessions)}</strong><small>sesiones</small></div></div><button class="btn" data-go="sim">${icon('sliders')}Ajustar inversión</button><p class="micro-note">Proyección con supuestos editables</p></aside></div><div id="summaryKpis">${kpis(r)}</div>${brand==='all'?`<div class="section-heading"><div><h2>Tres marcas. Tres formas de conectar.</h2><p>Entra a cada universo y descubre su estrategia.</p></div><span class="tag neutral">12 perfiles estratégicos</span></div><div class="brand-grid">${BRAND_IDS.map(id=>brandCard(id)).join('')}</div>`:`<div class="brand-strategy"><div class="strategy-item"><span class="eyebrow">TERRITORIO DE MARCA</span><h3>${B.position}</h3><p>${B.product}</p></div><div class="strategy-item"><span class="eyebrow">OBJETIVO DE COMUNICACIÓN</span><h3>De la afinidad a la acción.</h3><p>${B.objective}</p><div class="chips" style="margin-top:16px">${B.formats.map(f=>`<span class="chip">${f}</span>`).join('')}</div></div></div>`}<div class="two-cols"><section class="panel"><div class="panel-header"><div><h2>El mix que conecta.</h2><p>Distribución del escenario · ${shortMoney(r.spend)}</p></div><button class="text-button" data-go="media">Ver medios</button></div>${mixOverview(r)}</section><section class="panel insight-panel"><span class="eyebrow">UNA INVERSIÓN. MUCHAS POSIBILIDADES.</span><h2>Haz que cada peso tenga un propósito.</h2><p>Explora cómo cambia el alcance, los clics y las sesiones al mover tu presupuesto o la combinación de canales.</p><button class="btn ghost" data-go="sim">${icon('chart')}Abrir simulador</button></section></div><div class="scope-note">${icon('info')}<span>Escenario ilustrativo para planeación. Universo, costos y tasas son hipótesis editables; no son datos medidos de JGB ni estimaciones extraídas de plataformas. ${brand==='all'?'Los universos de las marcas pueden cruzarse; el alcance conjunto se modela sin sumarlos.':'Las audiencias son perfiles estratégicos, no listas de personas.'} <button class="text-button" data-action="method">Ver metodología</button></span></div>`}
function brandCard(id){const b=BRANDS[id];return `<a class="brand-card" style="${brandStyle(id)}" href="#${id}/summary"><div class="brand-card-art ${id}"><span>${id==='tarrito'?'Listos<br>para la<br>vida.':id==='pads'?'Tu<br>momento.<br>Tu ritual.':'Cuidado<br>que va<br>contigo.'}</span><img src="${b.image}" alt="${b.name}" loading="lazy"></div><div class="brand-card-body"><span class="category">${b.category}</span><h3>${b.name}</h3><p>${b.position}</p><div class="brand-card-foot"><span>4 perfiles · 5 medios</span><span>Explorar marca</span><i class="circle-icon">${icon('spark')}</i></div></div></a>`}
function mixOverview(r){let start=0;const gradient=r.config.mix.map((v,i)=>{const stop=start+v;const s=`${CHANNELS[i].color} ${start}% ${stop}%`;start=stop;return s}).join(',');return `<div class="mix-overview"><div class="donut" style="--segments:conic-gradient(${gradient})" role="img" aria-label="Distribución de inversión entre cinco medios"><div class="donut-inner"><strong>100%</strong><span>de tu inversión</span></div></div><div class="legend">${CHANNELS.map((c,i)=>`<div class="legend-row"><span><i style="background:${c.color}"></i>${c.name}</span><b>${pct(r.config.mix[i],1)}</b></div>`).join('')}</div></div>`}
function audiences(){const profiles=countProfiles();return `${header('Primero las personas. Luego los medios.','Explora hábitos, momentos de consumo y señales de afinidad para construir conexiones relevantes.','AUDIENCIAS / AFINIDADES')}<div class="intro-band"><div class="intro-copy"><div class="intro-symbol">${icon('users')}</div><div><h2>${brand==='all'?'Un portafolio conectado con la vida real.':BRANDS[brand].position}</h2><p>Colombia · compradores adultos · todos los géneros. Las edades foco orientan pruebas; no excluyen automáticamente a otros adultos.</p></div></div><div class="intro-count"><strong>${profiles.length}</strong><span>perfiles<br>estratégicos</span></div></div><div class="toolbar"><label class="search-field">${icon('search')}<input id="audienceSearch" type="search" placeholder="Busca una afinidad, un hábito o una marca" value="${esc(query)}" aria-label="Buscar audiencias"></label><div class="segmented" aria-label="Filtrar audiencias por etapa">${[['all','Todas'],['Descubrimiento','Descubrimiento'],['Consideración','Consideración'],['Intención','Intención']].map(([v,n])=>`<button data-stage="${v}" class="${stage===v?'active':''}" aria-pressed="${stage===v}">${n}</button>`).join('')}</div></div><div class="section-heading"><p id="audienceCount"></p><button class="text-button" data-action="export">${icon('download')}Exportar audiencias</button></div><div class="profile-grid" id="audienceResults">${profileResults()}</div><div class="audience-note">${icon('info')}<span>Perfiles ilustrativos, no tamaños medidos. Las afinidades y palabras clave son propuestas que deben validarse en cada plataforma. Los perfiles pueden superponerse y sus prioridades creativas no representan cuotas de población.</span></div>`}
function filteredProfiles(){const q=cleanText(query);return countProfiles().filter(p=>(stage==='all'||p.stage===stage)&&(!q||cleanText([p.name,p.label,p.why,BRANDS[p.brand].name,...p.interests,...p.moments,...p.keywords].join(' ')).includes(q)))}
function profileResults(){const list=filteredProfiles();queueMicrotask(()=>{const c=$('#audienceCount');if(c)c.textContent=`${list.length} de ${countProfiles().length} perfiles · ${BRANDS[brand].name}`});return list.length?list.map(p=>`<article class="profile-card" style="${brandStyle(p.brand)}"><div class="profile-cover"><div class="profile-symbol">${icon(p.icon)}</div><span class="profile-age">${p.age}<small>edad foco sugerida</small></span><span class="profile-brand">${BRANDS[p.brand].name}</span></div><div class="profile-body"><h3>${p.name}</h3><span class="label">${p.label} · ${p.stage}</span><p class="profile-quote">“${p.quote}”</p><div class="chips">${p.interests.slice(0,3).map(i=>`<span class="chip">${i}</span>`).join('')}</div><div class="profile-footer"><small>${p.channels.map(id=>CHANNELS.find(c=>c.id===id).short).join(' · ')}</small><button data-profile="${p.id}" aria-label="Ver perfil ${p.name}">Ver perfil</button></div></div></article>`).join(''):`<div class="empty-state"><h3>No encontramos esa afinidad.</h3><p>Prueba con “rutina”, “familia” o “cuidado”, o cambia el filtro de etapa.</p><button class="btn secondary" style="margin-top:20px" data-action="clear-audiences">Ver todos los perfiles</button></div>`}
function detailProfile(id){const p=PROFILES.find(p=>p.id===id);if(!p)return;openDialog(`<div class="dialog-heading"><span class="eyebrow">${BRANDS[p.brand].name} / ${p.label}</span><h2 id="dialogTitle">${p.name}</h2><p>Edad foco: ${p.age} · Colombia · ${p.stage}</p></div><div class="dialog-quote">“${p.quote}”</div><div class="detail-grid"><section><h3>¿Con quién conectamos?</h3><p>${p.why}</p></section><section><h3>Momentos de consumo</h3><div class="chips">${p.moments.map(v=>`<span class="chip">${v}</span>`).join('')}</div></section><section><h3>Señales de afinidad sugeridas</h3><div class="chips">${p.interests.map(v=>`<span class="chip">${v}</span>`).join('')}</div></section><section><h3>Búsquedas para explorar</h3><div class="chips">${p.keywords.map(v=>`<span class="chip">${v}</span>`).join('')}</div></section><section><h3>Mensaje propuesto</h3><p>${p.message}</p></section><section><h3>Idea de contenido</h3><p>${p.creative}</p></section><section class="detail-full"><h3>Activación en medios</h3><p>${p.activation}</p><div class="chips" style="margin-top:12px">${p.channels.map(v=>`<span class="tag neutral">${CHANNELS.find(c=>c.id===v).name}</span>`).join('')}</div></section><section><h3>Exclusiones y cuidado del mensaje</h3><p>${p.exclude}</p></section><section><h3>Qué observar</h3><p>${p.kpi}</p></section></div><div class="detail-callout"><b>Propuesta estratégica.</b> Este perfil no corresponde a una persona real ni a un público medido. Las señales son hipótesis para validar en plataforma; no se garantiza que cada interés exista como opción de segmentación. Prioridad creativa sugerida dentro de la marca: ${p.weight}% (no es tamaño de audiencia).</div><p style="margin-top:20px"><a class="source-link" href="${BRANDS[p.brand].source}" target="_blank" rel="noopener noreferrer">Consultar producto en el sitio oficial</a></p>`)}
function media(r){return `${header('El medio correcto. El momento preciso.','Cada plataforma tiene un papel dentro del plan. Combina descubrimiento, consideración e intención.','ECOSISTEMA / MEDIOS')}<div class="intro-band"><div class="intro-copy"><div class="intro-symbol">${icon('layers')}</div><div><h2>${OBJECTIVES[r.config.objective].description}</h2><p>Mix del escenario actual: ${shortMoney(r.spend)} COP durante ${r.config.days} días. Cambiar el objetivo actualiza la distribución sugerida.</p></div></div><div class="segmented" aria-label="Objetivo del plan">${Object.entries(OBJECTIVES).map(([id,o])=>`<button data-objective="${id}" class="${r.config.objective===id?'active':''}" aria-pressed="${r.config.objective===id}">${o.name}</button>`).join('')}</div></div><div class="channel-grid">${CHANNELS.map((c,i)=>`<article class="channel-card" style="--channel-color:${c.color}"><span class="channel-symbol">${c.symbol}</span><h3>${c.name}</h3><span class="role">${c.role}</span><p>${c.description}</p><div class="chips">${c.formats.map(f=>`<span class="chip">${f}</span>`).join('')}</div><div class="channel-card-foot"><div><strong>${pct(r.config.mix[i],1)}</strong><small>${shortMoney(r.rows[i].spend)} COP</small></div><button class="text-button" data-channel="${c.id}">Ver activación</button></div></article>`).join('')}<article class="channel-card channel-card-last"><span class="eyebrow">TU MEZCLA, TUS REGLAS</span><h3>Diseña el equilibrio<br>que necesita<br>tu marca.</h3><p>Ajusta cada porcentaje y proyecta lo que puede lograr tu inversión.</p><button class="btn ghost" data-go="sim">${icon('sliders')}Personalizar el mix</button></article></div><div class="section-heading"><div><h2>De la atención a la visita.</h2><p>Una función para cada etapa de comunicación.</p></div></div><div class="media-funnel"><article class="funnel-stage"><span class="eyebrow">DESCUBRIMIENTO</span><h3>Estar en su radar.</h3><p>Meta, TikTok y YouTube. Contenido nativo, alcance y recordación de marca.</p></article><article class="funnel-stage"><span class="eyebrow">CONSIDERACIÓN</span><h3>Darle una razón.</h3><p>Demostraciones, tutoriales y contextos de uso. Resolver dudas del producto.</p></article><article class="funnel-stage"><span class="eyebrow">INTENCIÓN</span><h3>Facilitar la visita.</h3><p>Search y mensajes de producto. Conectar búsquedas con destinos relevantes.</p></article></div><section class="panel" style="margin-top:24px"><div class="panel-header"><div><h2>Tu plan, medio por medio.</h2><p>Proyección del escenario ${SCENARIOS[r.config.scenario].name.toLowerCase()} · ${BRANDS[brand].name}</p></div><button class="text-button" data-action="export">${icon('download')}CSV</button></div>${resultsTable(r)}<p class="table-note">Costos y tasas ilustrativos, editables en el simulador. Search se calcula por CPC; los demás canales por CPM. Los resultados de tráfico no representan personas únicas ni ventas.</p></section>`}
function detailChannel(id){const c=CHANNELS.find(v=>v.id===id);if(!c)return;const relevant=countProfiles().filter(p=>p.channels.includes(id));openDialog(`<div class="dialog-heading"><span class="eyebrow">MEDIOS / ${BRANDS[brand].name}</span><h2 id="dialogTitle">${c.name}: ${c.role.toLowerCase()}.</h2><p>${c.description}</p></div><div class="detail-grid"><section><h3>Objetivo y compra</h3><p>${c.optimization}</p></section><section><h3>Señales de activación</h3><p>${c.signals}</p></section><section><h3>Formatos sugeridos</h3><div class="chips">${c.formats.map(f=>`<span class="chip">${f}</span>`).join('')}</div></section><section><h3>Cómo medir</h3><p>CPM y frecuencia para exposición; CTR y CPC para clics; sesiones y costo por sesión para llegada al sitio. Usar UTMs consistentes y validar el etiquetado de analítica.</p></section><section class="detail-full"><h3>Perfiles afines a este medio</h3><div class="chips">${relevant.map(p=>`<span class="tag neutral">${BRANDS[p.brand].short}: ${p.label}</span>`).join('')}</div></section>${id==='search'?`<section class="detail-full"><h3>Palabras clave para revisar</h3><div class="chips">${[...new Set(relevant.flatMap(p=>p.keywords))].slice(0,16).map(k=>`<span class="chip">${k}</span>`).join('')}</div></section>`:''}</div><div class="detail-callout"><b>Antes de activar:</b> confirmar disponibilidad de segmentaciones, elegibilidad del producto, destinos y volumen de inventario dentro de la plataforma. El mix es una propuesta de planeación; no activa campañas ni compromete inversión.</div>`)}
function resultsTable(r){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Medio</th><th>Inversión COP</th><th>Impresiones</th><th>Clics</th><th>Sesiones</th><th>CTR</th><th>Costo / sesión</th></tr></thead><tbody>${r.rows.map(c=>`<tr><td><strong class="table-channel"><i class="dot" style="background:${c.color}"></i>${c.name}</strong></td><td>${money(c.spend)}</td><td>${number(c.impressions)}</td><td>${number(c.clicks)}</td><td>${number(c.sessions)}</td><td>${pct(c.ctr,2)}</td><td>${c.sessions?money(c.spend/c.sessions):'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td>Total</td><td>${money(r.spend)}</td><td>${number(r.impressions)}</td><td>${number(r.clicks)}</td><td>${number(r.sessions)}</td><td>${pct(r.ctr,2)}</td><td>${r.sessions?money(r.cps):'—'}</td></tr></tfoot></table></div>`}
function narrative(r){return `Con <b>${money(r.spend)} COP</b> en <b>${number(r.config.days)} días</b>, el escenario ${SCENARIOS[r.config.scenario].name.toLowerCase()} proyecta <b>${number(r.reach)} personas alcanzadas</b> (${pct(r.coverage)} de una base hipotética de ${compact(r.universe)}), <b>${number(r.clicks)} clics</b> y <b>${number(r.sessions)} sesiones</b>.`}
function simulator(r){const c=r.config;return `${header('¿Y si inviertes un poco diferente?','Mueve las variables. Compara posibilidades. Encuentra una combinación de medios para tu próximo plan.','LABORATORIO / SIMULADOR')}<section class="sim-budget"><div><label for="budgetInput" class="budget-label">Tu inversión total en medios</label><div class="budget-field"><span>$</span><input type="number" id="budgetInput" data-field="budget" min="0" max="1000000" step="any" value="${c.budget/1e6}" aria-label="Inversión en millones de COP"><small>millones COP</small></div><div class="budget-tools">${[20,40,80,120].map(m=>`<button data-budget="${m}" class="${c.budget===m*1e6?'active':''}">$${m} M</button>`).join('')}</div></div><div class="budget-settings"><div class="field"><label for="daysInput">Duración · días</label><input id="daysInput" data-field="days" type="number" min="1" max="3650" value="${c.days}"></div><div class="field"><label for="universeInput">Universo · millones de personas</label><input id="universeInput" data-field="universe" type="number" min="0.000001" max="1000" step="any" value="${c.universe/1e6}"><small>Base hipotética editable</small></div><div class="field"><label for="objectiveInput">Objetivo del mix</label><select id="objectiveInput" data-select="objective">${Object.entries(OBJECTIVES).map(([id,o])=>`<option value="${id}" ${c.objective===id?'selected':''}>${o.name}</option>`).join('')}</select></div><div class="field"><label for="scenarioInput">Escenario de eficiencia</label><select id="scenarioInput" data-select="scenario">${Object.entries(SCENARIOS).map(([id,s])=>`<option value="${id}" ${c.scenario===id?'selected':''}>${s.name}</option>`).join('')}</select></div></div><div class="budget-range"><input class="range" id="budgetRange" type="range" data-field="budgetRange" min="0" max="${Math.max(200,Math.ceil(c.budget/1e6/50)*50)}" step="1" value="${c.budget/1e6}" style="--fill:${c.budget/1e6/Math.max(200,Math.ceil(c.budget/1e6/50)*50)*100}%" aria-label="Ajustar inversión en millones de COP"><div class="range-labels"><span>$0 M</span><span>Puedes escribir cualquier monto en el campo de inversión</span><span id="budgetRangeMax">$${Math.max(200,Math.ceil(c.budget/1e6/50)*50)} M</span></div></div></section><div id="simKpis" aria-live="polite" aria-atomic="true">${kpis(r)}</div><div class="sim-narrative" id="simNarrative">${narrative(r)}</div><div class="sim-layout"><div class="sim-main"><section class="panel"><div class="panel-header"><div><h2>El potencial de tu campaña.</h2><p>Acumulado estimado a lo largo de ${c.days} días</p></div><div class="chart-toolbar" aria-label="Métrica del gráfico">${[['reach','Alcance'],['clicks','Clics'],['sessions','Sesiones']].map(([id,name])=>`<button data-curve="${id}" class="${curveMetric===id?'active':''}" aria-pressed="${curveMetric===id}">${name}</button>`).join('')}</div></div><div id="projectionChart">${chart(r)}</div><div class="results-subgrid" id="subKpis">${subKpis(r)}</div></section><section class="panel"><div class="panel-header"><div><h2>Distribuye tu inversión.</h2><p>Los demás porcentajes se ajustan para mantener el 100%.</p></div><span class="tag neutral">Mix libre</span></div><div class="allocation">${CHANNELS.map((ch,i)=>`<div class="allocation-row"><span class="allocation-label"><i style="color:${ch.color}">${ch.symbol}</i>${ch.name}</span><label class="percent-input"><input data-mix="${i}" type="number" min="0" max="100" step="0.1" value="${Number(c.mix[i].toFixed(1))}" aria-label="Porcentaje de inversión ${ch.name}"><span>%</span></label><input class="range" type="range" min="0" max="100" step="1" value="${c.mix[i]}" data-mix-range="${i}" style="--fill:${c.mix[i]}%;--accent:${ch.color}" aria-label="Distribución de inversión ${ch.name}"><span class="allocation-money" data-mix-money="${i}">${money(r.rows[i].spend)} COP · ${compact(r.rows[i].clicks)} clics · ${compact(r.rows[i].sessions)} sesiones</span></div>`).join('')}</div><p class="allocation-note">Meta, TikTok, YouTube y Display se planean por CPM equivalente. Search usa CPC. El presupuesto total corresponde solo a pauta; no incluye honorarios, producción ni impuestos.</p></section></div><aside class="sim-sidebar">${brand==='all'?`<section class="panel"><div class="panel-header"><div><h2>Una inversión,<br>tres marcas.</h2><p>Reparte el presupuesto del portafolio.</p></div></div><div class="brand-allocation">${BRAND_IDS.map((id,i)=>`<div class="brand-alloc-row"><div class="brand-alloc-head"><img src="${BRANDS[id].image}" alt=""><span>${BRANDS[id].short}</span><label class="percent-input"><input type="number" min="0" max="100" step="0.1" data-share="${i}" value="${Number(c.shares[i].toFixed(1))}" aria-label="Porcentaje de inversión ${BRANDS[id].name}"><span>%</span></label></div><input class="range" type="range" min="0" max="100" data-share-range="${i}" value="${c.shares[i]}" style="--fill:${c.shares[i]}%;--accent:${BRANDS[id].color}" aria-label="Distribución por marca ${BRANDS[id].name}"><small data-share-money="${i}">${money(c.budget*c.shares[i]/100)} COP</small><label class="brand-universe">Base <input type="number" min="0.000001" max="1000" step="any" data-brand-universe="${id}" value="${state.contexts[id].universe/1e6}" aria-label="Universo de ${BRANDS[id].name} en millones"> M personas</label></div>`).join('')}</div><p class="allocation-note">Cada base se limita al universo total. Las tres marcas comparten el mix y los costos de este escenario. Sus escenarios individuales mantienen presupuestos y mix propios.</p></section>`:`<section class="panel"><span class="eyebrow">${BRANDS[brand].name}</span><h2 style="font-size:22px">Un escenario<br>solo para esta marca.</h2><p class="table-note">Esta inversión es independiente del presupuesto de la vista general. Los escenarios del portafolio reparten su propio monto entre las tres marcas.</p><button class="btn secondary" style="margin-top:20px" data-go="sim" data-brand="all">Ver portafolio</button></section>`}<section class="panel"><div class="panel-header"><div><h2>Lectura del escenario.</h2><p>Supuestos de eficiencia</p></div></div><div id="scenarioReading">${scenarioReading(r)}</div></section><aside class="model-note">${icon('info')}<h3>Proyecta con contexto.</h3><p>El alcance se satura al acercarse a la base potencial. No sumamos personas alcanzadas como si todos los públicos fueran distintos.</p><button class="text-button" data-action="method">Cómo se calcula</button></aside></aside></div><section class="panel"><div class="panel-header"><div><h2>Así se traduce tu plan.</h2><p>Resultados por plataforma · valores redondeados</p></div><span class="tag">Proyección</span></div><div id="simTable">${resultsTable(r)}</div><div id="brandResults">${brandResults(r)}</div></section><details class="advanced"><summary><div><h3>Personaliza los costos y las tasas.</h3><p>CPM, CPC, CTR, llegada a sesión y factor de repetición por medio.</p></div>${icon('sliders')}</summary><div class="advanced-body"><p class="scenario-note" id="scenarioParamNote">${scenarioParamNote(c)}</p><div class="table-wrap"><table class="data-table param-table"><thead><tr><th>Medio</th><th>Costo base COP</th><th>CTR base %</th><th>Sesión / clic %</th><th>Repetición base</th></tr></thead><tbody>${CHANNELS.map((ch,i)=>`<tr><td><strong>${ch.name}</strong></td><td><input type="number" min="1" max="${ch.buy==='CPC'?1e8:1e9}" step="any" data-param="${ch.buy==='CPC'?'cpc':'cpm'}" data-channel-index="${i}" value="${c.channels[i][ch.buy==='CPC'?'cpc':'cpm']}" aria-label="${ch.buy} base ${ch.name}"> ${ch.buy}</td><td><input type="number" min="0.001" max="100" step="any" data-param="ctr" data-channel-index="${i}" value="${c.channels[i].ctr}" aria-label="CTR base ${ch.name}"></td><td><input type="number" min="0" max="100" step="any" data-param="arrival" data-channel-index="${i}" value="${c.channels[i].arrival}" aria-label="Porcentaje llegada a sesión ${ch.name}"></td><td><input type="number" min="1" max="100" step="0.1" data-param="frequency" data-channel-index="${i}" value="${c.channels[i].frequency}" aria-label="Factor de repetición ${ch.name}"></td></tr>`).join('')}</tbody></table></div><p class="table-note">Estos valores son hipótesis de trabajo, no benchmarks certificados. Reemplázalos con datos históricos de la cuenta. La repetición base reduce contactos efectivos antes de aplicar la saturación; la frecuencia resultante se calcula como impresiones / alcance.</p></div></details><div class="sim-actions"><button class="btn" data-action="save">${icon('save')}Guardar escenario</button><button class="btn secondary" data-action="export">${icon('download')}Exportar plan CSV</button><button class="btn secondary" data-action="print">${icon('print')}Imprimir / PDF</button><button class="btn secondary" data-action="reset">${icon('reset')}Restablecer</button></div><div id="comparison">${comparison()}</div><div class="scope-note">${icon('info')}<span>Las proyecciones no garantizan entrega. Search requiere validar volumen de demanda; los clics y sesiones pueden incluir repeticiones. Duración reparte la inversión en el tiempo y no aumenta los resultados por sí sola. ${storageOK?'Los escenarios se guardan en este navegador.':'El navegador no permite guardar localmente; usa CSV para conservar el plan.'}</span></div>`}
function subKpis(r){return `<div><span>CPC estimado</span><strong>${r.clicks?money(r.cpc):'—'}</strong></div><div><span>Costo por sesión</span><strong>${r.sessions?money(r.cps):'—'}</strong></div><div><span>CPM equivalente</span><strong>${r.impressions?money(r.cpm):'—'}</strong></div><div><span>Inversión diaria</span><strong>${money(r.perDay)}</strong></div>`}
function scenarioReading(r){const data={prudent:['Costos +20%','CTR −20%','Llegada a sesión −10%'],base:['Costos base','CTR base','Llegada a sesión base'],optimistic:['Costos −15%','CTR +15%','Llegada a sesión +5%']}[r.config.scenario];return `<span class="tag" style="margin-bottom:16px">${SCENARIOS[r.config.scenario].name}</span><div class="legend">${data.map(t=>`<div class="legend-row"><span>${icon('check')}${t}</span></div>`).join('')}</div><p class="table-note">Variaciones relativas sobre los parámetros base. Son escenarios ilustrativos, no intervalos de confianza.</p>`}
function scenarioParamNote(c){return `Estás editando los <b>parámetros base</b>. Escenario seleccionado: <b>${SCENARIOS[c.scenario].name}</b>. ${c.scenario==='base'?'Se usan tal como los ingresas.':c.scenario==='prudent'?'Costos × 1,20; CTR × 0,80; llegada a sesión × 0,90.':'Costos × 0,85; CTR × 1,15; llegada a sesión × 1,05.'} Las tasas finales se limitan al 100%.`}
function chart(r){const metric=curveMetric,c=r.config,points=Array.from({length:25},(_,i)=>{const step=i/24;const p=project(state,brand,{...c,budget:c.budget*step});return {day:c.days*step,value:p[metric]}}),max=Math.max(1,r[metric]*1.15),w=600,h=240,left=58,right=14,top=14,bottom=33,x=v=>left+v/c.days*(w-left-right),y=v=>h-bottom-v/max*(h-top-bottom),line=points.map((p,i)=>`${i?'L':'M'}${x(p.day).toFixed(2)},${y(p.value).toFixed(2)}`).join(' '),fill=`${line} L${w-right},${h-bottom} L${left},${h-bottom} Z`,label={reach:'Personas alcanzadas',clicks:'Clics de enlace',sessions:'Sesiones estimadas'}[metric];return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}: ${number(r[metric])} al día ${c.days}. Proyección acumulada con inversión uniforme."><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${BRANDS[brand].color}" stop-opacity=".18"/><stop offset="100%" stop-color="${BRANDS[brand].color}" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(f=>`<line class="chart-grid" x1="${left}" y1="${y(max*f)}" x2="${w-right}" y2="${y(max*f)}"/><text x="${left-10}" y="${y(max*f)+4}" text-anchor="end">${compact(max*f)}</text>`).join('')}<path d="${fill}" fill="url(#chartFill)"/><path class="chart-line" d="${line}"/>${points.filter((_,i)=>i%6===0).map(p=>`<circle cx="${x(p.day)}" cy="${y(p.value)}" r="4" fill="white" stroke="${BRANDS[brand].color}" stroke-width="2"><title>Día ${number(p.day,1)}: ${number(p.value)} ${label.toLowerCase()}</title></circle><text x="${x(p.day)}" y="${h-10}" text-anchor="middle">Día ${number(p.day,1)}</text>`).join('')}</svg><div class="chart-caption"><span><i class="dot" style="color:var(--accent)"></i>${label}</span><span>Inversión diaria uniforme · alcance con saturación</span></div>`}
function brandResults(r){return r.brands.length?`<div class="mini-brand-results">${r.brands.map(b=>`<div class="mini-brand-result"><b style="color:${BRANDS[b.id].color}">${BRANDS[b.id].name}</b><strong>${compact(b.reach)}</strong><span>${pct(b.coverage)} de su base de ${compact(b.universe)}</span><span>${shortMoney(b.spend)} COP · ${compact(b.sessions)} sesiones</span></div>`).join('')}</div><p class="table-note">El alcance conjunto (${compact(r.reach)}) descuenta un cruce modelado entre marcas bajo un supuesto de independencia dentro del universo total. No equivale a una deduplicación medida. Los alcances por marca no se suman.</p>`:''}
function comparison(){const list=state.saved;return `<section class="comparison-card"><div class="panel-header"><div><h2>Compara tus posibilidades.</h2><p>Hasta seis escenarios guardados con sus parámetros.</p></div><span class="tag neutral">${list.length} guardados</span></div>${list.length?`<div class="table-wrap"><table class="data-table comparison-table"><thead><tr><th>Escenario</th><th>Inversión</th><th>Alcance</th><th>Cobertura</th><th>Clics</th><th>Sesiones</th><th>Acciones</th></tr></thead><tbody>${list.map((s,i)=>{const r=project(comparisonState(state,s),s.brand,s.config);return `<tr><td><strong>${esc(s.name)}</strong><br><small>${BRANDS[s.brand].name} · ${SCENARIOS[s.config.scenario].name}</small></td><td>${shortMoney(r.spend)}</td><td>${compact(r.reach)}</td><td>${pct(r.coverage)}</td><td>${compact(r.clicks)}</td><td>${compact(r.sessions)}</td><td><button class="small-btn" data-load="${i}" aria-label="Cargar escenario ${esc(s.name)}">Cargar</button><button class="small-btn danger" data-delete="${i}" aria-label="Eliminar escenario ${esc(s.name)}">Eliminar</button></td></tr>`}).join('')}</tbody></table></div>`:`<p class="comparison-empty">Tu siguiente plan puede empezar con una comparación. Ajusta la inversión y selecciona “Guardar escenario” para ver aquí sus resultados.</p>`}</section>`}
function updateOutputs(){const c=state.contexts[brand],r=project(state,brand);const updates={'#simKpis':kpis(r),'#simNarrative':narrative(r),'#projectionChart':chart(r),'#subKpis':subKpis(r),'#simTable':resultsTable(r),'#brandResults':brandResults(r),'#scenarioReading':scenarioReading(r),'#scenarioParamNote':scenarioParamNote(c)};for(const [selector,html]of Object.entries(updates)){const node=$(selector);if(node)node.innerHTML=html}$$('[data-mix-money]').forEach(el=>{const row=r.rows[+el.dataset.mixMoney];el.textContent=`${money(row.spend)} COP · ${compact(row.clicks)} clics · ${compact(row.sessions)} sesiones`});$$('[data-share-money]').forEach(el=>el.textContent=`${money(c.budget*c.shares[+el.dataset.shareMoney]/100)} COP`);$$('[data-budget]').forEach(el=>el.classList.toggle('active',+el.dataset.budget*1e6===c.budget));const b=$('#budgetInput'),range=$('#budgetRange');if(b&&document.activeElement!==b)b.value=c.budget/1e6;if(range){const max=Math.max(200,Math.ceil(c.budget/1e6/50)*50);range.max=max;range.value=c.budget/1e6;range.style.setProperty('--fill',`${c.budget/1e6/max*100}%`);$('#budgetRangeMax').textContent=`$${max} M`}const subtitle=$('#projectionChart')?.closest('.panel')?.querySelector('.panel-header p');if(subtitle)subtitle.textContent=`Acumulado estimado a lo largo de ${c.days} días`;persist()}
function syncMix(type){const c=state.contexts[brand],arr=type==='mix'?c.mix:c.shares;$$(`[data-${type}], [data-${type}-range]`).forEach(el=>{const idx=Number(el.dataset[type]??el.dataset[`${type}Range`]);if(document.activeElement!==el)el.value=Number(arr[idx].toFixed(1));if(el.type==='range')el.style.setProperty('--fill',`${arr[idx]}%`)});}
function openDialog(html){$('#dialogContent').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0;}
function method(){openDialog(`<div class="dialog-heading"><span class="eyebrow">TRANSPARENCIA / SUPUESTOS</span><h2 id="dialogTitle">Entiende lo que estás proyectando.</h2><p>Un modelo de planeación para explorar escenarios. No está conectado a cuentas publicitarias ni a analítica de JGB.</p></div><div class="method-steps"><section class="method-step"><h3>La base es una hipótesis, no un censo.</h3><p>Valores iniciales: portafolio 12 millones; Tarrito Rojo 8 millones; Pads 4 millones; Cuidaderm 5 millones. Son bases ilustrativas de personas adultas en Colombia, elegidas para modelar escenarios. No son cifras DANE, tamaños de Ads Manager ni estimaciones certificadas. Edita estas bases con información validada; en portafolio, cada base de marca se limita a la base total.</p></section><section class="method-step"><h3>De la inversión a las sesiones.</h3><p>Para Meta, TikTok, YouTube y Display usamos CPM equivalente. Search utiliza CPC: su volumen de impresiones se infiere con el CTR. La tasa de llegada a sesión resume carga de la página, medición y pérdidas entre clic y sesión. Clics y sesiones no representan usuarios únicos.</p><code>Impresiones CPM = inversión / CPM × 1.000<br>Clics CPM = impresiones × CTR / 100<br>Clics Search = inversión / CPC<br>Impresiones Search = clics / (CTR / 100)<br>Sesiones = clics × tasa de llegada / 100</code></section><section class="method-step"><h3>Alcance con saturación y repetición.</h3><p>Transformamos impresiones en contactos efectivos con un factor de repetición por medio. Una curva exponencial evita que el alcance supere el universo. Es una aproximación agregada: supone distribución homogénea de contactos, no valida disponibilidad del inventario ni deduplicación real entre medios.</p><code>Contactos efectivos = suma(impresiones de cada medio / repetición base)<br>Alcance de una marca = U × (1 − exp(−contactos efectivos / U))<br>Frecuencia resultante = impresiones / alcance<br>Cobertura = alcance / universo × 100</code></section><section class="method-step"><h3>Una vista general sin sumar públicos.</h3><p>En el portafolio, el presupuesto se reparte por marca; las marcas comparten mix, costos y tasas del escenario general. Calculamos primero el alcance de cada marca sobre su propia base. Luego aplicamos un supuesto de independencia dentro de la base común para estimar el cruce. Es una deduplicación modelada, no medida ni una garantía de separación de audiencias.</p><code>Alcance conjunto = U total × [1 − producto(1 − alcance de cada marca / U total)]</code></section><section class="method-step"><h3>Los porcentajes tienen denominador.</h3><p>Cobertura: personas alcanzadas / base hipotética. CTR: clics / impresiones. Llegada a sesión: sesiones / clics. El total de CTR y llegada a sesión se pondera por los volúmenes, nunca por un promedio simple de porcentajes. CPC y costo por sesión usan inversión en medios como numerador.</p></section><section class="method-step"><h3>Tres escenarios de eficiencia.</h3><p>Base usa los parámetros ingresados. Prudente aumenta costos 20%, reduce CTR 20% y llegada a sesión 10%. Optimista reduce costos 15%, aumenta CTR 15% y llegada a sesión 5%. Son variaciones relativas ilustrativas; no son intervalos estadísticos ni probabilidades. Las tasas finales tienen tope de 100%.</p></section><section class="method-step"><h3>Duración, dinero y límites de interpretación.</h3><p>La duración distribuye uniformemente la inversión en el tiempo; no multiplica resultados con el mismo presupuesto. Todos los montos están en COP y corresponden a inversión neta en pauta, sin impuestos, honorarios ni producción. Los cálculos no modelan cambios de subasta, disponibilidad, estacionalidad, conversiones ni ventas. Antes de ejecutar, validar los supuestos con históricos y herramientas de cada plataforma.</p></section></div><div style="margin-top:28px"><h3>Fuentes de producto</h3><p class="table-note">Información e imágenes oficiales consultadas el 19 de noviembre de 2026. Las estrategias de audiencia y parámetros de medios son propuestas de planeación propias.</p><div class="source-list">${BRAND_IDS.map(id=>`<a href="${BRANDS[id].source}" target="_blank" rel="noopener noreferrer">${BRANDS[id].sourceName}${icon('globe')}</a>`).join('')}</div><p class="table-note">Los datos y escenarios se guardan solo en el almacenamiento local de este navegador. Exporta el CSV si deseas conservar o compartir tu plan. No se envía información a plataformas publicitarias.</p></div>`)}
function saveDialog(){if(state.saved.length>=6){toast('Ya tienes seis escenarios. Elimina uno para guardar otro.');return}const c=state.contexts[brand];openDialog(`<div class="dialog-heading"><span class="eyebrow">GUARDAR / COMPARAR</span><h2 id="dialogTitle">Ponle nombre a tu escenario.</h2><p>${BRANDS[brand].name} · ${shortMoney(c.budget)} COP · ${SCENARIOS[c.scenario].name}</p></div><form id="saveForm"><div class="field"><label for="scenarioName">Nombre del escenario</label><input id="scenarioName" type="text" maxlength="64" required value="${BRANDS[brand].short} · ${shortMoney(c.budget)}" autocomplete="off"></div><p class="table-note">Se conserva en este navegador con su inversión, mezcla, universos, costos y tasas.</p><button type="submit" class="btn" style="margin-top:23px">${icon('save')}Guardar y comparar</button></form>`);}
function csvCell(v){const s=String(v??'');return `"${s.replace(/^[=+@-]/,"'$&").replace(/"/g,'""')}"`}
function downloadCsv(){const r=project(state,brand);let rows;if(view==='audiences'){rows=[['JGB Audience Lab','Audiencias estratégicas','Propuestas para validar en plataforma'],['Marca','Perfil','Edad foco','Etapa','Momentos','Afinidades sugeridas','Palabras clave sugeridas','Medios','Mensaje','Creatividad','Activación','Exclusiones','KPI','Prioridad creativa %'],...filteredProfiles().map(p=>[BRANDS[p.brand].name,p.name,p.age,p.stage,p.moments.join(' | '),p.interests.join(' | '),p.keywords.join(' | '),p.channels.join(' | '),p.message,p.creative,p.activation,p.exclude,p.kpi,p.weight])]}else{rows=[['JGB Audience Lab','Proyección ilustrativa, no resultados medidos'],['Marca / contexto',BRANDS[brand].name],['Fecha',new Date().toISOString()],['Inversión COP',r.spend],['Días',r.config.days],['Universo hipotético',r.universe],['Eficiencia',SCENARIOS[r.config.scenario].name],['Objetivo del mix',OBJECTIVES[r.config.objective].name],['Alcance modelado',r.reach],['Cobertura %',r.coverage],['Impresiones',r.impressions],['Clics',r.clicks],['CTR % de impresiones',r.ctr],['Sesiones',r.sessions],['Sesión / clic %',r.arrival],['Frecuencia',r.frequency],['CPC COP',r.cpc],['Costo por sesión COP',r.cps],[],['Medio','Inversión COP','Participación %','Impresiones','Clics','Sesiones','CTR final %','Sesión/clic final %','CPM equivalente COP','CPC final COP','Compra','Costo base COP','CTR base %','Sesión/clic base %','Repetición base'],...r.rows.map((row,i)=>[row.name,row.spend,r.config.mix[i],row.impressions,row.clicks,row.sessions,row.ctr,row.arrival,row.cpm,row.cpc,row.buy,r.config.channels[i][row.buy==='CPC'?'cpc':'cpm'],r.config.channels[i].ctr,r.config.channels[i].arrival,r.config.channels[i].frequency]),[],['Marca','Inversión COP','Participación %','Universo efectivo','Alcance modelado','Cobertura %','Clics','Sesiones'],...r.brands.map((b,i)=>[BRANDS[b.id].name,b.spend,r.config.shares[i],b.universe,b.reach,b.coverage,b.clicks,b.sessions]),[],['Supuestos','Universos y tasas hipotéticos. Inversión neta de pauta sin honorarios, impuestos ni producción.'],['Alcance marca','U * (1 - exp(-sum(impresiones/repetición)/U))'],['Alcance portafolio','U total * (1 - producto(1 - alcance marca/U total)); independencia modelada, no medida.'],['Sesiones','Clics * llegada a sesión. No son ventas ni personas únicas.'],['Eficiencia','Prudente: costo x1.2, CTR x0.8, llegada x0.9. Optimista: costo x0.85, CTR x1.15, llegada x1.05.'],...BRAND_IDS.map(id=>['Fuente de producto',BRANDS[id].source])]}const blob=new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`JGB_${brand}_${view==='audiences'?'audiencias':'plan'}_${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV preparado con los datos y supuestos del escenario.')}
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.classList.contains('skip-link')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}if(el.dataset.go){go(el.dataset.go,el.dataset.brand||brand);return}if(el.dataset.profile){detailProfile(el.dataset.profile);return}if(el.dataset.channel){detailChannel(el.dataset.channel);return}if(el.dataset.stage){stage=el.dataset.stage;$$('[data-stage]').forEach(b=>{b.classList.toggle('active',b.dataset.stage===stage);b.setAttribute('aria-pressed',String(b.dataset.stage===stage))});$('#audienceResults').innerHTML=profileResults();return}if(el.dataset.objective){state.contexts[brand]=applyObjective(state.contexts[brand],el.dataset.objective,brand);persist();render();return}if(el.dataset.budget){state.contexts[brand].budget=Number(el.dataset.budget)*1e6;updateOutputs();return}if(el.dataset.curve){curveMetric=el.dataset.curve;$$('[data-curve]').forEach(b=>{b.classList.toggle('active',b.dataset.curve===curveMetric);b.setAttribute('aria-pressed',String(b.dataset.curve===curveMetric))});$('#projectionChart').innerHTML=chart(project(state,brand));return}if(el.dataset.load!==undefined){const saved=state.saved[Number(el.dataset.load)];if(saved){state.contexts[saved.brand]=structuredClone(saved.config);if(saved.brand==='all')for(const id of BRAND_IDS)state.contexts[id].universe=saved.universes[id];persist();go('sim',saved.brand);toast('Escenario cargado. Puedes seguir ajustándolo.')}return}if(el.dataset.delete!==undefined){state.saved.splice(Number(el.dataset.delete),1);persist();$('#comparison').innerHTML=comparison();toast('Escenario eliminado de este navegador.');return}switch(el.dataset.action){case'menu':$('#sidebar').classList.toggle('open');$('#scrim').hidden=!$('#sidebar').classList.contains('open');el.setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')));syncNavigation();break;case'method':method();break;case'close-dialog':$('#dialog').close();break;case'clear-audiences':query='';stage='all';render();break;case'export':downloadCsv();break;case'print':window.print();break;case'save':saveDialog();break;case'reset':{const original=defaults();state.contexts[brand]=original.contexts[brand];if(brand==='all')for(const id of BRAND_IDS)state.contexts[id].universe=original.contexts[id].universe;persist();render();toast('Restablecido el escenario inicial de $40 millones.');break}}});
$('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('[data-action="menu"]')?.setAttribute('aria-expanded','false');syncNavigation()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('[data-action="menu"]')?.setAttribute('aria-expanded','false');syncNavigation()}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='audienceSearch'){query=el.value;$('#audienceResults').innerHTML=profileResults();return}if(!el.matches('input'))return;let c=state.contexts[brand];if(el.value===''||!Number.isFinite(Number(el.value)))return;const v=Number(el.value);if(el.dataset.field){if(el.dataset.field==='budget'||el.dataset.field==='budgetRange')c.budget=finite(v*1e6,c.budget,0,1e12);else if(el.dataset.field==='days')c.days=finite(v,c.days,1,3650);else if(el.dataset.field==='universe')c.universe=finite(v*1e6,c.universe,1,1e9);updateOutputs()}else if(el.dataset.mix!==undefined||el.dataset.mixRange!==undefined){c.mix=redistribute(c.mix,Number(el.dataset.mix??el.dataset.mixRange),v);syncMix('mix');updateOutputs()}else if(el.dataset.share!==undefined||el.dataset.shareRange!==undefined){c.shares=redistribute(c.shares,Number(el.dataset.share??el.dataset.shareRange),v);syncMix('share');updateOutputs()}else if(el.dataset.brandUniverse){const id=el.dataset.brandUniverse;state.contexts[id].universe=finite(v*1e6,state.contexts[id].universe,1,1e9);updateOutputs()}else if(el.dataset.param){const key=el.dataset.param,index=Number(el.dataset.channelIndex);const limits={cpm:[1,1e9],cpc:[1,1e8],ctr:[.001,100],arrival:[0,100],frequency:[1,100]};c.channels[index][key]=finite(v,c.channels[index][key],...limits[key]);updateOutputs()}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.select){const c=state.contexts[brand];if(el.dataset.select==='objective'){state.contexts[brand]=applyObjective(c,el.value,brand);syncMix('mix')}else c.scenario=el.value;updateOutputs();return}if(el.matches('input[type="number"]')&&el.id!=='scenarioName'){if(el.value===''||!el.checkValidity()){toast('Se ajustó el valor al rango permitido.');const c=state.contexts[brand];if(el.dataset.field)el.value=el.dataset.field==='budget'?c.budget/1e6:el.dataset.field==='universe'?c.universe/1e6:c.days;else if(el.dataset.param)el.value=c.channels[+el.dataset.channelIndex][el.dataset.param];else if(el.dataset.brandUniverse)el.value=state.contexts[el.dataset.brandUniverse].universe/1e6;else if(el.dataset.mix!==undefined)el.value=Number(c.mix[+el.dataset.mix].toFixed(1));else if(el.dataset.share!==undefined)el.value=Number(c.shares[+el.dataset.share].toFixed(1));}}});
document.addEventListener('submit',event=>{if(event.target.id!=='saveForm')return;event.preventDefault();const name=$('#scenarioName').value.trim();if(!name)return;state.saved.push({name,brand,created:new Date().toISOString(),config:structuredClone(state.contexts[brand]),universes:Object.fromEntries(BRAND_IDS.map(id=>[id,state.contexts[id].universe]))});const saved=persist();$('#dialog').close();$('#comparison').innerHTML=comparison();toast(saved?'Escenario guardado. Ya puedes compararlo.':'Escenario disponible esta sesión. Exporta CSV para conservarlo.');});
window.addEventListener('hashchange',route);
window.addEventListener('resize',syncNavigation);
route();
